using namespace std;

template <typename T=string>
class Library {

    public:

    std::vector<Book> bookCollections{};

    Library(){
        std::vector<Book> bookCollections{};
    }

    //: Adds a new book to the library.
    void add_book(const Book& book){

        bookCollections.push_back(book);
    }
    //: Removes a book from the library based on its title.
    T remove_book(const std::string& title){
        //needs to first find the matching book before removing
         bookCollections.pop_back();
         return 0;
    }
    //: Searches for a book by title and returns it (if found) or prints an error message.
    T find_book(const std::string& title){

        auto byTitle = bookCollections;
         std::views::filter([&](string n)->string{ if(n == title)return n ;});
        ranges::for_each(byTitle, ([](string n)->string{return n;}));

        //std::range::;
        return "not found";
    }
    //: Returns a collection of books written by the specified author.
    T get_books_by_author(const std::string& author){

        auto byAuthor = bookCollections;
         std::views::filter([&](string n)->string{ if(n == author)return n;});
        ranges::for_each(byAuthor, ([](string n)->string{return n;}));
        //std::range::
        return "not found";
    }
    //: Returns a collection of books belonging to the specified genre.
    T get_books_by_genre(const std::string& genre){

        auto byGenre = bookCollections;
         std::views::filter([&](string n)->string{ if(n == genre)return n;});
        ranges::for_each(byGenre, ([](string n)->string{return n;}));

        // std::range::;
        // find()
        return "not found";
    }

    void printBooks(){
        cout<<"The books currently in the library: \n"<<endl;
        for(vector<Book>::iterator it = bookCollections.begin(); it<bookCollections.end(); ++it){

            //cout<<*it;
            //it.title;
            //bookCollections;
            std::cout<<"Title: "<<it->getTitle()<<setw(35)<<" Author: "<<it->getAuthor()<<setw(10)<<endl;

        }
    }

    // Use a std::vector<Book>::iterator to traverse the books in the library.
    // Use an iterator to display all books in the library.
    // Implement an iterator-based search function that finds books by author.


};

